'use strict';
let upgradeData;
function upgradePct(value){return `${(value*100).toFixed(1)}%`}
function upgradeRecord(x){return `${x.wins} correct · ${x.losses} missed`}
function upgradeScore(p,g){
 if(!p)return 'No line available';
 const total=Math.max(Math.abs(p.margin)+2,p.total);
 let home=Math.max(0,Math.round((total+p.margin)/2)),away=Math.max(0,Math.round((total-p.margin)/2));
 if(home===away){if(p.margin>=0)home++;else away++}
 return `${name(g.away)} ${away} · ${name(g.home)} ${home}`;
}
