  function upsetCard(r){const picked=r.pickedTeam,opp=picked===r.home?r.away:r.home,ex=r.explanation,winScore=picked===r.home?r.homeScore:r.awayScore,otherScore=picked===r.home?r.awayScore:r.homeScore;
    return `<article class="pr-upset"><div class="pr-upset-top"><span class="pr-hit">OUTRIGHT WIN</span><span>${niceDate(easternDate(r.date))}</span></div><div class="pr-team">${logo(picked)}<div><h3>${esc(name(picked))} <span>+${Math.abs(r.homeSpread)}</span></h3><p>${r.neutral?'Neutral site':picked===r.home?'Home underdog':'Road underdog'} vs. ${esc(name(opp))}</p></div></div><div class="pr-final"><b>${winScore} <span>–</span> ${otherScore}</b><span>FINAL · ${esc(name(picked))} won</span></div><div class="pr-saved"><span>Our saved pick</span><b>${esc(name(picked))} to win</b><small>By ${Math.abs(r.predictedHomeMargin).toFixed(1)} points${r.pickWinProbability!=null?' · '+(r.pickWinProbability*100).toFixed(1)+'% win chance':''}</small></div><h4>Why we picked it</h4><p>${esc(ex?.pregame||'The saved forecast favored this team. Detailed input contributions were not archived.')}</p><h4>What happened</h4>${(ex?.recap||['The final score confirms the outright win.']).map(t=>`<p>${esc(t)}</p>`).join('')}<details class="pr-evidence"><summary>See the pick’s evidence</summary><p>Pick saved ${esc(stamp(r.forecastAt))}. ${r.archiveType==='recovered_saved_forecast'?'Recovered from an older saved forecast file.':'Archived by the daily updater.'}</p><p>Underdog label comes from the saved spread, checked ${esc(stamp(r.quoteRetrievedAt))}${r.quoteProvider?' · '+esc(r.quoteProvider):''}.</p>${ex?.drivers?.length?`<p>Points toward ${esc(name(picked))}; negative values favored the opponent.</p><div class="pr-drivers">${[{factor:'Model starting value',pointsTowardPick:ex.baselineTowardPick},...ex.drivers].map(d=>`<div><span>${esc(d.factor)}</span><b>${signed(d.pointsTowardPick)}</b></div>`).join('')}</div>`:''}<p>Game stats describe the result. They do not prove what caused the win.</p><a href="${esc(r.sourceArchive)}" target="_blank" rel="noreferrer">Saved prediction ↗</a>${r.sourceUrl?' · <a href="'+esc(r.sourceUrl)+'" target="_blank" rel="noreferrer">Final box score ↗</a>':''}</details></article>`;
  }
